import Link from 'next/link'
import type { ListingLifecycleAction, ProductListResult, ProductStatus, VendorProduct } from '@/lib/vendor/catalog'
import { ListingLifecycleBadge } from './ListingLifecycleBadge'
import { ProductStatusBadge } from './ProductStatusBadge'

interface Props { result: ProductListResult; onStatusChange: (product: VendorProduct, status: ProductStatus) => void; onLifecycleAction: (product: VendorProduct, action: ListingLifecycleAction) => void; onPageChange: (page: number) => void }
export function ProductTable({ result, onStatusChange, onLifecycleAction, onPageChange }: Props) { return <><div className="catalog-table-wrap"><table className="catalog-table"><caption className="sr-only">Vendor product catalog</caption><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>Approval</th><th>Listing</th><th>Updated</th><th>Actions</th></tr></thead><tbody>{result.items.map((product) => <tr key={product.id}><td><Link href={`/vendor/products/${product.id}`} className="catalog-product-name">{product.name}</Link></td><td>{product.sku}</td><td>{product.category}</td><td>₹{product.price.toLocaleString('en-IN')}</td><td>{product.stock}</td><td><ProductStatusBadge status={product.status} /></td><td><ListingLifecycleBadge status={product.lifecycleStatus} /></td><td>{new Date(product.updatedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</td><td><div className="catalog-actions"><Link href={`/vendor/products/${product.id}/edit`} aria-label={`Edit ${product.name}`}>Edit</Link>{product.status === 'draft' || product.status === 'rejected' || product.status === 'vendor_fix_required' ? <button type="button" onClick={() => onStatusChange(product, 'submitted')}>Submit</button> : null}{product.status === 'approved' && product.lifecycleStatus === 'active' ? <button type="button" onClick={() => onLifecycleAction(product, 'deactivate')}>Deactivate</button> : null}{product.status === 'approved' && product.lifecycleStatus === 'inactive' ? <button type="button" onClick={() => onLifecycleAction(product, 'activate')}>Activate</button> : null}{product.status === 'approved' && product.lifecycleStatus !== 'archived' ? <button type="button" onClick={() => onLifecycleAction(product, 'archive')}>Archive</button> : null}{product.lifecycleStatus === 'archived' ? <button type="button" onClick={() => onLifecycleAction(product, 'restore')}>Restore</button> : null}</div></td></tr>)}</tbody></table></div><div className="catalog-pagination"><span>{result.total ? `Showing ${(result.page - 1) * result.pageSize + 1}-${Math.min(result.page * result.pageSize, result.total)} of ${result.total}` : 'No products'}</span><div><button type="button" disabled={result.page <= 1} onClick={() => onPageChange(result.page - 1)}>Previous</button><strong>{result.page} / {result.totalPages}</strong><button type="button" disabled={result.page >= result.totalPages} onClick={() => onPageChange(result.page + 1)}>Next</button></div></div></> }